-- Grant postgres membership in the service account role
GRANT "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal" TO postgres;
GRANT "sa-cloudsql-clr-airflow-test@2e5bc18a.internal" TO postgres;

-- ownership change
REASSIGN OWNED BY "sa-cloudsql-clr-airflow-test@2e5bc18a.internal" TO "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal";

-- revoke the membership after
REVOKE "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal" FROM postgres;
REVOKE "sa-cloudsql-clr-airflow-test@2e5bc18a.internal" FROM postgres;

-- grant privileges to new user
GRANT USAGE ON SCHEMA airflow_clearing TO "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal";
GRANT CREATE ON SCHEMA airflow_clearing TO "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal";
GRANT ALL ON SCHEMA airflow_clearing TO "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal";
{code}
- set default postgres schema for the "new" account
{code}
ALTER ROLE "sa-cloudsql-clr-airflow-acc@2e5bc18a.internal" SET search_path = airflow_clearing;
{code}
- deploy airflow with WIF config;;;

